M="pharm-tox"
SUB="Toxicities & Miscellaneous"
T={
"cardio":[("Which drug causes dose-dependent dilated cardiomyopathy?",["Doxorubicin","Vancomycin","Niacin","Sumatriptan"],0,"Anthracyclines; dexrazoxane is cardioprotective."),
 ("Diffuse flushing during a rapid vancomycin infusion is due to:",["Non-IgE histamine release","IgE-mediated anaphylaxis","Coronary vasospasm","QT prolongation"],0,"Slow the infusion and give antihistamines."),
 ('A 58-year-old woman treated for breast cancer 2 years ago now has progressive exertional dyspnea. Echocardiography shows a dilated left ventricle with LVEF 30%; her regimen included a cumulative-dose-limited anthracycline. The mechanism of her cardiomyopathy is:', ['Free radical generation damaging myocytes', 'Coronary vasospasm causing infarction', 'Hypersensitivity myocarditis with eosinophils', 'HER2 blockade with reversible dysfunction'], 0, 'Doxorubicin causes dose-dependent, largely irreversible cardiomyopathy via free radicals; trastuzumab (anti-HER2) causes reversible dysfunction.', 3)],
"endorx":[("Nephrogenic diabetes insipidus is a classic adverse effect of:",["Lithium","Carbamazepine","Spironolactone","Metoclopramide"],0,"Also demeclocycline; carbamazepine causes SIADH."),
 ("Hyperprolactinemia with galactorrhea is most likely from:",["Risperidone","Bromocriptine","Cabergoline","Levodopa"],0,"D₂ blockade removes dopamine's inhibition of prolactin."),
 ('A 45-year-old man with bipolar disorder, stable on lithium for 10 years, has polyuria of 6 L/day. Serum Na⁺ is 146 mEq/L and urine osmolality is 150 mOsm/kg, unchanged after desmopressin. The mechanism of his polyuria is:', ['Reduced collecting-duct response to ADH', 'Decreased ADH release from the pituitary', 'Osmotic diuresis from hyperglycemia', 'Primary polydipsia from psychiatric illness'], 0, 'Lithium causes nephrogenic DI by impairing ADH-stimulated aquaporin-2 insertion; failure to concentrate after desmopressin excludes central DI.', 3)],
"girx":[("Pill-induced esophagitis is typical of:",["Doxycycline, bisphosphonates, KCl","Metformin, sitagliptin, insulin","Omeprazole, famotidine, sucralfate","Loperamide, ondansetron, statins"],0,"Also NSAIDs. Take with a full glass of water and stay upright."),
 ("Which drug pair is classically linked to pancreatitis?",["Valproate and didanosine","Metformin and insulin","Warfarin and heparin","Amoxicillin and clavulanate"],0,"Also azathioprine, glucocorticoids and some diuretics."),
 ('A 30-year-old woman taking doxycycline for acne swallows her dose at bedtime with a sip of water and lies down. Two days later she has severe pain on swallowing; endoscopy shows a single discrete ulcer in the mid-esophagus with normal surrounding mucosa. Most likely diagnosis:', ['Pill-induced esophagitis', 'Candida esophagitis', 'Herpes simplex esophagitis', 'Eosinophilic esophagitis'], 0, 'Tablets lodged near the aortic arch cause local ulceration; Candida gives white plaques, usually in immunosuppressed patients.', 2)],
"hemerx":[("Hemolysis in G6PD deficiency can be triggered by:",["Primaquine, dapsone, rasburicase","Penicillin, cephalexin, azithromycin","Warfarin, heparin, apixaban","Amlodipine, lisinopril, atenolol"],0,"Also sulfonamides and nitrofurantoin. Oxidant stress; Heinz bodies and bite cells."),
 ("Which drug causes megaloblastic anemia by interfering with folate?",["Methotrexate","Chloramphenicol","Heparin","Clozapine"],0,"Also trimethoprim, phenytoin; hydroxyurea and 5-FU impair DNA synthesis."),
 ('A 28-year-old Thai man is given primaquine to prevent relapse of P. vivax malaria. Three days later he has dark urine and jaundice; Hb is 8.2 g/dL and the smear shows bite cells. A supravital stain of his blood would most likely show:', ['Heinz bodies', 'Howell–Jolly bodies', 'Basophilic stippling', 'Ringed sideroblasts'], 0, 'Oxidant drugs in G6PD deficiency precipitate denatured hemoglobin (Heinz bodies), which splenic macrophages remove to make bite cells; Howell–Jolly bodies indicate asplenia.', 3)],
"mskrx":[("Gingival hyperplasia is a side effect of:",["Phenytoin, cyclosporine, CCBs","Lithium, haloperidol, sertraline","Warfarin, heparin, clopidogrel","Statins, ezetimibe, niacin"],0,"Good oral hygiene reduces it."),
 ("Tendon rupture is associated with:",["Fluoroquinolones","Tetracyclines","Macrolides","Penicillins"],0,"Risk higher with age and glucocorticoids."),
 ('A 72-year-old man taking prednisone for COPD is treated for community-acquired pneumonia with an oral antibiotic. Five days later he feels a pop at the back of his ankle while climbing stairs and cannot stand on tiptoe. Which antibiotic was he most likely given?', ['Levofloxacin', 'Azithromycin', 'Doxycycline', 'Amoxicillin'], 0, 'Fluoroquinolones cause tendinopathy and Achilles rupture, especially in older patients on glucocorticoids; macrolides do not.', 2)],
"neurorx":[("Tinnitus, headache and vertigo (cinchonism) are caused by:",["Quinine or quinidine","Isoniazid or ethambutol","Vincristine or paclitaxel","Linezolid or metronidazole"],0,"Antimalarial/antiarrhythmic."),
 ("Which drug lowers the seizure threshold?",["Bupropion","Valproate","Levetiracetam","Lorazepam"],0,"Also imipenem, isoniazid, tramadol."),
 ('A 24-year-old woman with bulimia nervosa is started on an oral medication to help her quit smoking. Two weeks later she has a generalized tonic–clonic seizure; she has no prior seizure history. Which drug was most likely prescribed?', ['Bupropion', 'Varenicline', 'Nicotine patch', 'Nortriptyline'], 0, 'Bupropion lowers the seizure threshold and is contraindicated in bulimia and anorexia; varenicline is not associated with seizures in this way.', 3)],
"renalrx":[("Hemorrhagic cystitis is caused by:",["Cyclophosphamide","Cisplatin","Methotrexate","Mercaptopurine"],0,"Acrolein metabolite; prevented with mesna."),
 ("Drug-induced lupus is classically caused by:",["Hydralazine and procainamide","Losartan and amlodipine","Furosemide and spironolactone","Metformin and glipizide"],0,"Anti-histone antibodies; renal involvement is uncommon."),
 ('A 60-year-old man taking hydralazine for hypertension for a year develops arthralgia, a facial rash and pleuritic chest pain. Urinalysis and creatinine are normal. Which antibody is most likely positive?', ['Anti-histone antibodies', 'Anti-dsDNA antibodies', 'Anti-Smith antibodies', 'Anti-centromere antibodies'], 0, 'Drug-induced lupus (hydralazine, procainamide, isoniazid) is marked by anti-histone antibodies and spares the kidneys; anti-dsDNA suggests idiopathic SLE.', 3)],
"multirx":[("A disulfiram-like reaction with alcohol occurs with:",["Metronidazole","Amoxicillin","Azithromycin","Doxycycline"],0,"Aldehyde dehydrogenase inhibition → acetaldehyde accumulation."),
 ("Which drug combination raises ototoxicity risk most?",["Aminoglycoside + loop diuretic","Amoxicillin + clavulanic acid","Atorvastatin + ezetimibe","Omeprazole + calcium carbonate"],0,"Both are ototoxic; cisplatin and vancomycin are others."),
 ('A 40-year-old woman being treated for bacterial vaginosis drinks two glasses of wine at a party. Within 20 minutes she has facial flushing, throbbing headache, nausea and palpitations. The mechanism of this reaction is:', ['Inhibition of aldehyde dehydrogenase', 'Inhibition of alcohol dehydrogenase', 'Release of histamine from mast cells', 'Blockade of MAO in the gut wall'], 0, 'Metronidazole causes a disulfiram-like reaction by blocking aldehyde dehydrogenase, so acetaldehyde accumulates; blocking alcohol dehydrogenase would prevent acetaldehyde formation.', 3)],
"cyp":[("A woman on oral contraceptives starts rifampin. Expected effect:",["↓ Contraceptive efficacy","↑ Serum estrogen levels","No clinically relevant change","↑ Thrombotic risk from estrogen"],0,"Rifampin induces CYP3A4; use backup contraception."),
 ("Which drug inhibits CYP450 and can raise warfarin levels?",["Amiodarone","Rifampin","Carbamazepine","St John’s wort"],0,"Also fluconazole, metronidazole, cimetidine, macrolides."),
 ('A 65-year-old man has a stable INR of 2.5 on warfarin. He is treated with trimethoprim–sulfamethoxazole for a urinary tract infection, and 5 days later has gum bleeding with INR 6.1. The main mechanism of this interaction is:', ['Inhibition of CYP2C9-mediated metabolism', 'Induction of CYP3A4-mediated metabolism', 'Increased gut absorption of vitamin K', 'Reduced renal excretion of warfarin'], 0, 'Sulfamethoxazole inhibits CYP2C9, which clears the more potent S-warfarin; an inducer would lower the INR instead.', 3)],
"sulfa":[("A patient with sulfa allergy needs a loop diuretic. Which lacks a sulfonamide group?",["Ethacrynic acid","Furosemide (IV)","Bumetanide (IV)","Torsemide (oral)"],0,"Ethacrynic acid is more ototoxic."),
 ("Which of these is a sulfa drug?",["Celecoxib","Ibuprofen","Naproxen","Aspirin"],0,"Also sulfasalazine, sulfonylureas, probenecid, thiazides, acetazolamide."),
 ('A 48-year-old woman with a history of hives after trimethoprim–sulfamethoxazole develops a similar urticarial rash a week after starting a new drug for ulcerative colitis. Which drug was most likely started?', ['Sulfasalazine', 'Mesalamine', 'Budesonide', 'Vedolizumab'], 0, 'Sulfasalazine is split into 5-ASA and sulfapyridine, a sulfonamide; mesalamine is 5-ASA alone without the sulfa moiety.', 3)],
"names":[("A drug ending in -gliflozin is a:",["SGLT2 inhibitor","DPP-4 inhibitor","GLP-1 agonist","Sulfonylurea"],0,"-gliptin = DPP-4; -glutide = GLP-1 agonist."),
 ("The suffix -zumab means a monoclonal antibody that is:",["Humanized","Chimeric","Fully human","A receptor fusion protein"],0,"-ximab chimeric, -umab human, -cept fusion protein."),
 ('A 54-year-old man with type 2 diabetes (HbA1c 8.4%) on metformin is started on empagliflozin. Two months later he has a genital fungal infection. The new drug acts by:', ['Blocking glucose reabsorption in proximal tubule', 'Inhibiting breakdown of endogenous incretins', 'Closing K-ATP channels on pancreatic β cells', 'Activating PPAR-γ in adipose tissue'], 0, '-gliflozins inhibit SGLT2, causing glucosuria and genital mycotic infections; -gliptins inhibit DPP-4 to prolong incretins.', 3)],
"terato":[("Which antihypertensive class is contraindicated in pregnancy?",["ACE inhibitors and ARBs","Combined α/β-blockers","Centrally acting α₂ agonists","Dihydropyridine CCBs"],0,"Fetal renal damage and oligohydramnios. Labetalol, methyldopa and nifedipine are used in pregnancy."),
 ("Ebstein anomaly is associated with fetal exposure to:",["Lithium","Valproate","Warfarin","Isotretinoin"],0,"Valproate → neural tube defects."),
 ('A woman with bipolar disorder took a mood stabilizer throughout the first trimester. Prenatal testing showed elevated maternal serum AFP, and her newborn has a lumbosacral myelomeningocele. Which drug did she most likely take?', ['Valproate', 'Lithium', 'Quetiapine', 'Lamotrigine'], 0, 'Valproate inhibits folate-related pathways and causes neural tube defects; lithium is linked to Ebstein anomaly.', 2)],
"pgx":[("Before starting carbamazepine in a Thai patient, test for:",["HLA-B*15:02","HLA-B*57:01","HLA-B*58:01","TPMT"],0,"Risk of SJS/TEN."),
 ("Prolonged apnea after succinylcholine suggests:",["Pseudocholinesterase deficiency","Slow N-acetyltransferase 2 phenotype","CYP2D6 ultrarapid metabolizer","Ryanodine receptor (RYR1) mutation"],0,"Inherited butyrylcholinesterase variant."),
 ('A 40-year-old Thai man with recurrent gout starts a urate-lowering drug. Four weeks later he has fever, a widespread rash, eosinophilia and elevated transaminases. Which genetic test could have identified his risk before treatment?', ['HLA-B*58:01', 'HLA-B*15:02', 'HLA-B*57:01', 'HLA-DRB1*04'], 0, 'HLA-B*58:01 predicts severe cutaneous reactions (SJS/TEN, DRESS) to allopurinol, common in Thai and Han Chinese; B*15:02 is for carbamazepine.', 3)],
}
